		string column_names;
		for (const auto &idx : GetLogicalIndexes(columns)) {
			auto &col = columns.GetColumn(idx);
			column_names += "_" + col.Name();
		}
		return type_name + "_" + table + column_names;
	}

	void SetColumnName(string name) {
		if (!columns.empty()) {
			return;
		}
		columns.push_back(std::move(name));
