+//! Push Byte
+void IteratorCurrentKey::Push(uint8_t byte) {
+	if (cur_key_pos == key.size()) {
+		key.push_back(byte);
+	}
+	D_ASSERT(cur_key_pos < key.size());
+	key[cur_key_pos++] = byte;
