+bool IteratorCurrentKey::operator>(const Key &k) const {
+	for (idx_t i = 0; i < MinValue<idx_t>(cur_key_pos, k.len); i++) {
+		if (key[i] > k.data[i]) {
+			return true;
+		} else if (key[i] < k.data[i]) {
+			return false;
+		}
+	}
+	return cur_key_pos > k.len;
