		D_ASSERT(info.l_node->type == NodeType::NLeaf);
		D_ASSERT(info.r_node->type == NodeType::NLeaf);
		auto has_constraint = info.l_art->IsPrimary() || info.l_art->IsUnique();
		return Leaf::Merge(has_constraint, info.l_node, info.r_node);
	}
