+	for (idx_t i = 0; i < args.size(); i++) {
+		uint8_t bytes[16];
+		for (int i = 0; i < 16; i += 4) {
+			*reinterpret_cast<uint32_t *>(bytes + i) = lstate.random_engine.NextRandomInteger();
