+static float JaccardSimilarity(string_t str, string_t txt) {
+	if (str.GetSize() < 1 || txt.GetSize() < 1) {
+			throw InvalidInputException("Jaccard Function: An argument too short!");
+		}
+	std::map<string_t, int64_t> ms, mt, mu;
