+	}
+	auto coptions = reinterpret_cast<duckdb::CFileOpenOptions *>(options);
+
+	duckdb::FileOpenFlags open_flags;
+	switch (flag) {
+	case DUCKDB_FILE_FLAGS_READ:
+		coptions->read = value;
+		break;
+	case DUCKDB_FILE_FLAGS_WRITE:
+		coptions->write = value;
+		break;
+	case DUCKDB_FILE_FLAGS_APPEND:
