+	}
+
+	// Assign the new (not updated) children to the end of the result vector.
+	for (idx_t i = 1; i < args.ColumnCount(); i++) {
+		if(!updated[i]) {
+			result_child_entries[starting_child_entries.size() + i - 1]->Reference(args.data[i]);
+		}
+	}
+
+	result.Verify(args.size());
