+		// right side is constant: result is flat vector
+		result.vector_type = VectorType::FLAT_VECTOR;
+		result.sel_vector = left.sel_vector;
+		result.count = left.count;
+		if (right.nullmask[0]) {
+			result.nullmask.set();
+			return;
+		}
+		result.nullmask = left.nullmask;
