        }
        state = duckdb_appender_destroy(&appender);
        if (state == DuckDBError) {
            fprintf(stderr, "err: %d", state);
            FAIL("Failed to destroy appender");
        }
        if (i % 500 == 0) {
            printf("completed %d\n", i);
			duckdb_query(con, "checkpoint", NULL);
        }
    }

    // cleanup
    duckdb_disconnect(&con);
    duckdb_close(&db);
	REQUIRE(1==1);
}

