+		state.Print("<tr>");
+		for(idx_t i=0; i<data.size(); i++){
+			state.Print("<td>");
+			output_html_string(data[i] ? data[i] : state.nullValue);
+			state.Print("</td>\n");
+		}
+		state.Print("</tr>\n");
+	}
+
+	/*
+	** Output the given string with characters that are special to
+	** HTML escaped.
+	*/
+	void output_html_string(const char *z){
+		if( z==0 ) z = "";
+		string escaped;
+		for(; *z; z++ ) {
+			switch(*z) {
+			case '<':
+				escaped += "&lt;";
+				break;
+			case '&':
+				escaped += "&amp;";
+				break;
+			case '>':
+				escaped += "&gt;";
+				break;
+			case '\"':
+				escaped += "&quot;";
+				break;
+			case '\'':
+				escaped += "&#39;";
+				break;
+			default:
+				escaped += *z;
+			}
+		}
+		state.Print(escaped);
+	}
+};
