		if( z==0 ) z = "";
		string escaped;
		for(; *z; z++ ) {
			switch(*z) {
			case '<':
				escaped += "&lt;";
				break;
			case '&':
				escaped += "&amp;";
				break;
			case '>':
				escaped += "&gt;";
