+			switch (result->types[col_idx]) {
+			case TypeId::BOOLEAN:
+				varvalue = PROTECT(NEW_LOGICAL(nrows));
+				break;
+			case TypeId::TINYINT:
+			case TypeId::SMALLINT:
+			case TypeId::INTEGER:
+				varvalue = PROTECT(NEW_INTEGER(nrows));
+				break;
+			case TypeId::BIGINT:
+			case TypeId::DECIMAL:
+				varvalue = PROTECT(NEW_NUMERIC(nrows));
+				break;
+			case TypeId::VARCHAR:
+				varvalue = PROTECT(NEW_STRING(nrows));
+				break;
