+					break;
+				case TypeId::INTEGER:
+					vector_to_r<uint32_t, uint32_t>(chunk->data[col_idx], INTEGER_POINTER(dest), dest_offset,
+					                                NA_INTEGER);
+					break;
+				case TypeId::BIGINT:
+					vector_to_r<uint64_t, double>(chunk->data[col_idx], NUMERIC_POINTER(dest), dest_offset, NA_REAL);
