ScalarFunctionSet ConstRHSDivideFun::GetFunctions() {
	ScalarFunctionSet functions;
	for (auto &type : LogicalType::Integral()) {
		functions.AddFunction(ScalarFunction({type, type}, type, GetConstDivideFunction(type)));
	}
	return functions;
}
