 	Leaf *r_n = (Leaf *)r_node;

 	// push row_ids of l_n in a map to avoid duplicates
 	unordered_map<row_t, bool> l_n_row_ids;
 	for (idx_t i = 0; i < l_n->num_elements; i++) {
 		l_n_row_ids[l_n->GetRowId(i)] = true;
 	}

