 	if (capacity == 0) {
 		for (auto &data : owned_data) {
 			data.Initialize(new_capacity);
 		}
 	} else {
 		for (auto &data : owned_data) {
 			data.Resize(new_capacity);
 		}
 	}
 	capacity = new_capacity;
