 namespace duckdb {

 bool UUID::FromString(string str, hugeint_t &result) {
 	auto hex2char = [](char ch) -> unsigned char {
 		if (ch >= '0' && ch <= '9')
 			return ch - '0';
 		if (ch >= 'a' && ch <= 'f')
 			return 10 + ch - 'a';
 		if (ch >= 'A' && ch <= 'F')
 			return 10 + ch - 'A';
 		return 0;
 	};
 	auto is_hex = [](char ch) -> bool {
 		return (ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F');
 	};

 	if (str.empty())
 		return false;
 	int hasBraces = 0;
 	if (str.front() == '{')
 		hasBraces = 1;
 	if (hasBraces && str.back() != '}')
 		return false;

 	result.lower = 0;
 	result.upper = 0;
 	size_t count = 0;
 	for (size_t i = hasBraces; i < str.size() - hasBraces; ++i) {
 		if (str[i] == '-')
 			continue;
 		if (count >= 32 || !is_hex(str[i]))
 			return false;
 		if (count >= 16) {
 			result.lower = (result.lower << 4) | hex2char(str[i]);
 		} else {
 			result.upper = (result.upper << 4) | hex2char(str[i]);
 		}
 		count++;
 	}
 	return count == 32;
 }

