+				next_state = SQLParseState::NORMAL;
+				break;
+			}
+			zSql += 2;
+			while (zSql[0] && (zSql[0] != '*' || zSql[1] != '/')) {
+				zSql++;
+			}
+			if (zSql[0] == 0) {
+				// unterminated c-style string
+				return false;
+			}
+			zSql++;
+			next_state = SQLParseState::WHITESPACE;
+			break;
+		}
+		case '-': { /* SQL-style comments from "--" to end of line */
