+		if (!is_valid) {
+			return;
+		}
+		PatasCompression<EXACT_TYPE, false>::Store(value, state.patas_state);
+		group_idx++;
+		if (group_idx == PatasPrimitives::CHIMP_SEQUENCE_SIZE) {
