 string TextTreeRenderer::RemovePadding(string l) {
 	idx_t start = 0, end = l.size();
 	while (start < l.size() && IsPadding(l[start])) {
 		start++;
 	}
 	while (end > 0 && IsPadding(l[end - 1])) {
 		end--;
 	}
 	return l.substr(start, end - start);
 }

