+		for (auto &item : fields) {
+			auto &name_p = item.first;
+			auto &type_p = item.second;
+			string name = py::str(name_p);
+			if (!py::isinstance<DuckDBPyType>(type_p)) {
+				string actual_type = py::str(type_p.get_type());
